{
  "name": "Alicat质量流量计",
  "name_en": "Alicat Mass Flow Meter",
  "manufacturer": "Alicat",
  "description": "Alicat质量流量计是一种用于气体流量测量的实验室仪表，通常可同时提供质量流量、体积流量、压力和温度读数，并可进行气体种类选择、零点校准和累计量管理。它常用于气体供给、混气、工艺监测和各类气体实验系统。",
  "description_en": "An Alicat mass flow meter is a laboratory instrument for measuring gas flow. It typically provides mass flow, volumetric flow, pressure, and temperature readings, and may support gas selection, zeroing, and totalizer management. It is commonly used in gas delivery, gas mixing, process monitoring, and general gas-handling experimental systems.",
  "tag_hints": [
    "mass flow meter",
    "gas flow measurement",
    "pressure monitoring",
    "temperature monitoring",
    "gas selection",
    "totalizer",
    "gas mixture configuration"
  ],
  "actions": [
    {
      "action_name": "auto-is_connected",
      "description": "检查指定通信端口上是否连接了该流量计。",
      "description_en": "Check whether this flow meter is connected on the specified communication port."
    },
    {
      "action_name": "auto-get",
      "description": "读取当前状态与测量值，如压力、温度、质量流量和体积流量。",
      "description_en": "Read the current status and measured values, such as pressure, temperature, mass flow, and volumetric flow."
    },
    {
      "action_name": "auto-set_gas",
      "description": "设置仪器当前使用的气体种类。",
      "description_en": "Set the current gas type used by the instrument."
    },
    {
      "action_name": "auto-create_mix",
      "description": "在仪器中创建一个自定义气体混合配置。",
      "description_en": "Create a custom gas mixture configuration in the instrument."
    },
    {
      "action_name": "auto-delete_mix",
      "description": "删除仪器中的一个自定义气体混合配置。",
      "description_en": "Delete a custom gas mixture configuration from the instrument."
    },
    {
      "action_name": "auto-lock",
      "description": "锁定仪器面板按键，防止本机误操作。",
      "description_en": "Lock the instrument front-panel buttons to prevent local accidental operation."
    },
    {
      "action_name": "auto-unlock",
      "description": "解锁仪器面板按键。",
      "description_en": "Unlock the instrument front-panel buttons."
    },
    {
      "action_name": "auto-is_locked",
      "description": "查询仪器面板按键是否处于锁定状态。",
      "description_en": "Query whether the instrument front-panel buttons are locked."
    },
    {
      "action_name": "auto-tare_pressure",
      "description": "对压力测量执行清零校准。",
      "description_en": "Perform a tare operation on the pressure measurement."
    },
    {
      "action_name": "auto-tare_volumetric",
      "description": "对体积流量测量执行清零校准。",
      "description_en": "Perform a tare operation on the volumetric flow measurement."
    },
    {
      "action_name": "auto-reset_totalizer",
      "description": "重置累计流量计数器。",
      "description_en": "Reset the totalized flow counter."
    },
    {
      "action_name": "auto-get_firmware",
      "description": "读取仪器固件版本。",
      "description_en": "Read the instrument firmware version."
    },
    {
      "action_name": "auto-flush",
      "description": "读取并清空待处理通信数据。",
      "description_en": "Read and clear any pending communication data."
    },
    {
      "action_name": "auto-close",
      "description": "关闭与仪器的通信连接。",
      "description_en": "Close the communication connection to the instrument."
    }
  ]
}

